begin;
create extension if not exists pgtap with schema extensions;
select plan(16);
update public.role_permissions set allowed=false where company_id='10000000-0000-0000-0000-000000000003' and role='manager' and permission='edit';
-- Person 5 is a Contributor in RS Learning; here they hold a different Role in Aleem.
update public.members set role='viewer' where company_id='10000000-0000-0000-0000-000000000003' and person_id='20000000-0000-0000-0000-000000000005';
select is((select count(*)::int from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p') and not c.relrowsecurity),0,'every public table has RLS');
select is((select count(*)::int from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p') and c.relname not in ('agents','companies','people','setup_claim') and not exists (select 1 from pg_attribute a where a.attrelid=c.oid and a.attname='company_id' and not a.attisdropped)),0,'company-owned tables have company_id');
set local role anon;
select is((select count(*)::int from public.companies),0,'anonymous companies denied');
select is((select count(*)::int from public.people),0,'anonymous people denied');
select is((select count(*)::int from public.members),0,'anonymous members denied');
select is((select count(*)::int from public.role_permissions),0,'anonymous permissions denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select count(*)::int from public.companies),1,'manager sees one company');
select is((select count(*)::int from public.companies where slug='aleem'),0,'other company hidden');
select is((select count(*)::int from public.people where id <> auth.uid()),9,'company teammates visible');
select is((select count(*)::int from public.members where company_id <> '10000000-0000-0000-0000-000000000001'),0,'other company members hidden');
select is((select count(*)::int from public.role_permissions where company_id <> '10000000-0000-0000-0000-000000000001'),0,'other company permissions hidden');
select is((select count(*)::int from public.role_permissions where role in ('contributor','viewer') and permission='approve' and allowed),0,'contributors and viewers cannot approve');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000005',true);
select is((select count(*)::int from public.companies),2,'multi-company member sees two companies');
select isnt((select role::text from public.members where person_id=auth.uid() and company_id='10000000-0000-0000-0000-000000000001'),(select role::text from public.members where person_id=auth.uid() and company_id='10000000-0000-0000-0000-000000000003'),'roles are per company');
select is((select allowed from public.role_permissions where company_id='10000000-0000-0000-0000-000000000001' and role='manager' and permission='edit'),true,'RS permission is stored per company');
select is((select allowed from public.role_permissions where company_id='10000000-0000-0000-0000-000000000003' and role='manager' and permission='edit'),false,'Aleem permission can differ');
select * from finish();
rollback;
